        self.몸.setx(self.몸.xcor() - 설정.걸음)
    def 오른쪽(self):
        self.몸.setx(self.몸.xcor() + 설정.걸음)
    def 위(self):
        self.몸.sety(self.몸.ycor() + 설정.걸음)
    def 아래(self):
        self.몸.sety(self.몸.ycor() - 설정.걸음)

