        self.몸.shape("circle")
        self.몸.color("gold")
        self.몸.penup()
        self.새자리()
    def 새자리(self):
        x = random.randint(-9, 9) * 20
        y = random.randint(-6, 6) * 20
        self.몸.goto(x, y)

